# The decision resources as a host declares them for the trial page: tenant-scoped,
# with a read policy of the host's own after the generated bypass. They sit on the
# tenant tables `tenant_resources.ex` already uses.
#
# The trial reads as the actor with no engine context, so the bypass does not apply
# and this policy is the whole answer to "may this person try this decision".

defmodule AshDecisions.TrialHost.Definition do
  @moduledoc false
  use AshDecisions.Resources.Definition,
    domain: AshDecisions.TrialHost.Domain,
    repo: AshDecisions.TestRepo,
    table: "tenant_dmn_definitions",
    tenant?: true

  policies do
    policy action_type(:read) do
      authorize_if(actor_attribute_equals(:decisions?, true))
    end
  end
end

defmodule AshDecisions.TrialHost.Evaluation do
  @moduledoc false
  use AshDecisions.Resources.Evaluation,
    domain: AshDecisions.TrialHost.Domain,
    repo: AshDecisions.TestRepo,
    definition: AshDecisions.TrialHost.Definition,
    table: "tenant_dmn_evaluations",
    tenant?: true
end

defmodule AshDecisions.TrialHost.Domain do
  @moduledoc false
  use Ash.Domain

  resources do
    resource(AshDecisions.TrialHost.Definition)
    resource(AshDecisions.TrialHost.Evaluation)
  end
end
